using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change #1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so preserve it explicitly.
            entity.HasDiscriminator().HasValue("Blog");
            entity.ToContainer("Blogs");
            entity.HasProperty("Discriminator");

            // Breaking change #2: EF 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents use "Blog|1" format, so opt back in to the legacy format.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();

            // Breaking change #3: EF 9 no longer supports HasIndex on Cosmos provider.
            // Removed: entity.HasIndex(b => b.Name);
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        // Breaking change #1 (alt fix): Tell EF 9 to keep the old "Discriminator" property name.
        options.UseCosmos("AccountEndpoint=...;AccountKey=...", "BlogDb",
            cosmosOptions =>
            {
                // No built-in option exists; we handle via HasDiscriminator above.
            });
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

