class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // FIX Breaking Change #1 - Discriminator property renamed to "$type" in EF 9.
            // Existing documents store "Discriminator", so keep using it.
            entity.HasDiscriminator<string>("Discriminator")
                  .HasValue<Blog>("Blog");

            // FIX Breaking Change #2 - id format changed from "EntityType|KeyValue" to just "KeyValue".
            // Existing documents have id = "Blog|1", so use IdProperty convention workaround.
            entity.Property(b => b.Id).ToJsonProperty("id");
            entity.UsePropertyAccessMode(PropertyAccessMode.Property);

            // FIX Breaking Change #3 - HasIndex() throws on Cosmos in EF 9.
            // REMOVED: entity.HasIndex(b => b.Name);
            // Cosmos indexing is managed via indexing policy on the container, not EF.
        });
    }
}

