class SyncJob
{
    void Run(BlogContext context)
    {
        // FIX Breaking Change #4 - Raw SQL queries now use FromSql (not FromSqlRaw)
        // and parameterized interpolation in EF 9. Also, since we preserved
        // "Discriminator" in OnModelCreating, existing queries still work.
        // Example raw query fix:
        //   OLD: context.Blogs.FromSqlRaw("SELECT * FROM c WHERE c.Discriminator = 'Blog'")
        //   NEW: context.Blogs.FromSql($"SELECT * FROM c WHERE c.Discriminator = 'Blog'")

        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

